import crypto from 'node:crypto';
import type { Pool } from 'pg';

export function normalizeVnPhone(raw: string): string {
  const digits = raw.replace(/\D+/g, '');
  if (digits.startsWith('84')) return `0${digits.slice(2)}`;
  if (!digits.startsWith('0') && digits.length === 9) return `0${digits}`;
  return digits;
}

export function sha256MetaField(value: string): string {
  return crypto.createHash('sha256').update(value.trim().toLowerCase()).digest('hex');
}

export async function ingestLeadWith180DayDedup(
  pool: Pool,
  tenantId: string,
  rawPhone: string,
  ports: string[],
) {
  const phone = normalizeVnPhone(rawPhone);
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    await client.query("SELECT set_config('app.current_tenant_id', $1, true)", [tenantId]);

    // 1. Loc trung SĐT trong 6 thang (180 ngay) tranh dot 35% chi phi Ads
    const dup = await client.query(
      `SELECT id, assigned_port FROM crm_leads
       WHERE tenant_id = $1 AND phone_normalized = $2
         AND created_at >= now() - interval '180 days'
       LIMIT 1`,
      [tenantId, phone],
    );
    if (dup.rowCount && dup.rowCount > 0) {
      await client.query('COMMIT');
      return { status: 'DUPLICATE_180D', existingLeadId: dup.rows[0].id };
    }

    // 2. Khoa advisory-lock chia vong Round-Robin 5 cong ZaloBot cong bang
    await client.query('SELECT pg_advisory_xact_lock(hashtext($1))', [tenantId]);
    const cursorRes = await client.query(
      `UPDATE tenant_round_robin SET last_index = (last_index + 1) % $2
       WHERE tenant_id = $1 RETURNING last_index`,
      [tenantId, ports.length],
    );
    const port = ports[cursorRes.rows[0].last_index];
    const inserted = await client.query(
      `INSERT INTO crm_leads (tenant_id, phone_normalized, assigned_port, stage)
       VALUES ($1, $2, $3, 'new_lead') RETURNING id`,
      [tenantId, phone, port],
    );
    await client.query('COMMIT');
    return { status: 'DISPATCH_ZALOBOT', leadId: inserted.rows[0].id, port };
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release();
  }
}

export async function sendMetaCapiQualifiedEvent(pixelId: string, token: string, phone: string) {
  const res = await fetch(`https://graph.facebook.com/v21.0/${pixelId}/events?access_token=${token}`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      data: [
        {
          event_name: 'QualifiedLead',
          event_time: Math.floor(Date.now() / 1000),
          action_source: 'system_generated',
          user_data: { ph: [sha256MetaField(normalizeVnPhone(phone).replace(/^0/, '84'))] },
        },
      ],
    }),
  });
  return { httpStatus: res.status, ok: res.status === 200 };
}
